ranked AS (
    SELECT
        c.id,
        c.cmplid,
        c.odino,
        c.mfr_name,
        c.modeltxt,
        c.compdesc,
        c.cdescr,
        1 - (c.embedding <=> q.qv) AS score,
        ROW_NUMBER() OVER (ORDER BY c.embedding <=> q.qv) AS rank
    FROM complaints c, q
)
